def exact(a,b):
 return json.dumps(a,sort_keys=True,separators=(',',':'),allow_nan=False)==json.dumps(b,sort_keys=True,separators=(',',':'),allow_nan=False)

def encoded(i):
 if i.kind=='adrpc':return (0xA000|(i.args[0]<<8)|(i.args[1]//4)).to_bytes(2,'little')
 if i.kind=='multiple':return (0xC000|(int(i.args[0])<<11)|(i.args[1]<<8)|i.args[2]).to_bytes(2,'little')
 return menu.encoded(i)

