 for row in LISTS:
  need(d.u32(raw,row['table_cell'])==row['address'],'actual context/topic cell')
  b=chunk(raw,row['address'],row['size']);need(b[-1]==255 and 255 not in b[:-1],'complete finite ID list including EOS')

