 def read(self,a,n):
  v=super().read(a,n)
  if not 0x08000000<=a<0x0A000000:self.trace.append(('read',a,n))
  if self.pc in ROOT['byte_reads']:self.reads.append((a,n))
  if self.pc in(ROOT['selected_index_read'],ROOT['submenu_pointer_read']):self.events.append(dict(role='actual_rom_or_generated_index_read',site=self.pc,address=a,size=n,value=v))
