 def write(self,a,n,v):
  super().write(a,n,v);self.trace.append(('write',a,n))
  if a in(CONTEXT,HELP+1,VIDEO+21,LIST+14,LIST+13):self.events.append(dict(role='actual_producer_store',site=self.pc,address=a,size=n,value=v))
 def step(self,*a,**kw):
  i=self.instructions[self.pc];k,x=i.kind,i.args;r=self.reg
  self.site_counts[self.pc]=self.site_counts.get(self.pc,0)+1
  if k=='adrpc':r[x[0]]=((self.pc+4)&~3)+x[1];self.pc+=2;self.steps+=1;return
  if k=='multiple'and x[0]:
   _,rb,mask=x
   for j in range(8):
    if mask&(1<<j):r[j]=self.read(r[rb],4);r[rb]+=4
   self.pc+=2;self.steps+=1;return
